-- aar/w3/aar_row_629_draft2.sql. DRAFT 2 by W3 (draft 1 5c05a977: W1 PASS WITH N1, Wall 11977; N1 applied, nothing else: Wall 11971 is W4's write post and Wall 11975 W1's readback) (session_01H1X3ANsGiMnhnbkfphocmo) for the coordinator (seat 36). NOT RUN by W3.
-- One ask_aar_snapshots row for ASK 629 (a free reserve past a JFL-moved seat; a "returned no text" failure line) and its ask_aar_builders row.
-- Every value is from Wall 11919, 11921 (first 1,300 characters each), 11929, 11930, 11951, 11952, 11957, 11958, 11971 and 11975 (read whole by W3), W4's files under /mnt/project-files/ask629/w4/ (md5sum by W3; notes629.md read whole; write629_run.txt read in its last lines), audit_log row 42086 (read by W3), and W4's thread note to W3 of 05:19 CST 2026-11-25 (the two cards; kept in aar/w3/cards_629_635_from_w4.md).
-- NOT READ by W3: the cards themselves; plan629.md beyond its md5; W1's grade and readback files in git; n8n.
-- md5_written: the engine target as written, the b2 rebase on dc258730, md5 0e720823. W1 graded the b1 target 55d96341 PASS WITH N1 to N3 (Wall 11952) and confirmed the b2 target as differing from live only on the two nodes, both byte-equal to b1 (Wall 11958: REBASE CONFIRMED; the b1 grade carries). The grades element for 0e720823 is that confirmation.
-- objective_met is 'in part': written and read back MATCH; shown offline on stored runs; no live run since the write.
-- After the insert: SELECT * FROM ask_aar_snapshots_check(); SELECT * FROM ask_aar_grades_check();
-- The session line below must be the coordinator's own session; written_by is read from it.
BEGIN;
SET LOCAL truth.session_id = '<COORDINATOR SESSION, registered to seat 36>';
WITH s AS (
INSERT INTO ask_aar_snapshots (ask, rev, title, objective, objective_met, objective_met_reason, objective_source, written_by, prior_row, operator_words, card, owner_seat, plan, build_files, revert, grades, md5_written, audit_ids, objects, tests, readbacks, run_evidence, manuals, status, sources)
VALUES (629, '1', $t$ASK 629: the reserve is the first free seat after the panel that is neither JFL-moved nor time-removed, and a judge reply with no text fails with a line that names the cause$t$,
  $t$Run 42517 stopped at Panel Check: hydrogen, a panel judge, spent 65,533 of its 65,536 output tokens on reasoning and returned no text; the engine called it "an envelope this parser does not recognise"; and no reserve was free, because the one seat the engine looked at for the reserve (the fourth free seat) was JFL-moved, although other seats had accepted. One empty reply ended a paid run with no row. This ASK (A) makes the reserve the first seat after the panel that is neither JFL-moved nor time-removed, and (B) makes a reply whose content is not text fail with "returned no text: finish_reason ...; output tokens ... (reasoning ...); prompt tokens ...". No reasoning setting, model setting, order or alternate order is touched. (plan rev 0, ask629/w4/plan629.md md5 2d000472; Wall 11919, 11929)$t$,
  'in part',
  $t$Written by W4 at 05:15 CST 2026-11-25 on the operator's press "Write it" (05:14 CST; written, Wall 11971; audit 42086), and read back MATCH by W1 (Wall 11975). Engine dc258730 to 066525aa, two nodes, two lines, 423 nodes; child aad0ad9c unchanged. Init Seats: panel_reserve is the first seat of the free list after the panel that is neither JFL-moved nor time-removed, or none; before, it was the fourth free seat or none. Panel Check envelope(): a choices reply whose message content is not a string throws "FAIL-CLOSED: seat <s> returned no text: finish_reason <f>; output tokens <n> (reasoning <r>); prompt tokens <p>. NO ROW IS WRITTEN.", placed just before the old generic throw, after every parse branch; a field not given prints "not given". IN PART, because it is shown offline only (t629, 39 PASS, 0 FAIL, by W4 and by W1): the base code reproduces the stored Init Seats of runs 42528, 42517, 42505 and 42373 and on each only the reserve changes, from none to qwen4max (42373, 42505) or sonnet (42517, 42528); with the fourth seat eligible the output is byte-equal to the old; with every later seat JFL-moved the reserve is still none; on the 42517 replay the old Panel Check throws as stored and the new one makes one substitution (slot 3, hydrogen to sonnet, kind no_usable_judgment, reason "empty reply") with the detail "returned no text: finish_reason length; output tokens 65,536 (reasoning 65,533); prompt tokens 75,848"; envelope() is byte-equal on nine other reply forms. FINDING of the build: every replayable live run since ASK 591 had no reserve, because the fourth free seat was JFL-moved. W1's R1 (a substituted reserve must not also sit as an alternate): met by the alternate guard G3, which refuses a model already on the panel; an unused reserve is still offered. NOT SHOWN: no live run since the write; W1 N2: the post-substitution payloads of R1 were built by hand; W1 N1: array content was refused before and still is, now under the new wording; W4 did not read the majority count code, which the change does not touch. The build was made on engine 2df7f6fa (b1, target 55d96341) and rebuilt on dc258730 after ASK 626 was written (b2, target 0e720823); W1 confirmed the rebase. Open: two clean live runs (the operator's rule of 10:38 CST 2026-11-24); the reserve path fires only when a panel judge fails. The engine manual pairs (parts 10.0 and 16.0) are graded PASS WITH N1 and not written at the time of this draft.$t$,
  '11919, 11921, 11929, 11930, 11951, 11952, 11957, 11958, 11971, 11975',
  current_setting('truth.session_id'), NULL,
  to_jsonb($t$(1) W4's build card (cmsg_017ZQamDMHrS6fqMHnQDVo58FnekiCDK9BGVVCqMzSfdkx, "Build ASK 629: a free reserve past a JFL-moved seat, and a clearer failure line?"): he pressed "Build it" at 04:35 CST 2026-11-25. (2) W4's write card (cmsg_017ZQamDMHrS6fqMHnQDVo5897xTxTTneDRVdxsjea7sQ8, "Write ASK 629 (reserve past a moved seat, no-text failure line) to the live engine?"): he pressed "Write it" at 05:14 CST 2026-11-25. Both are from W4's thread note to W3 of 05:19 CST 2026-11-25; W3 did not read the cards.$t$::text),
  $j${"answer": "Write it", "question": "Write ASK 629 (reserve past a moved seat, no-text failure line) to the live engine?", "thread": "W4", "card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo5897xTxTTneDRVdxsjea7sQ8", "press_time": "05:14 CST 2026-11-25", "build_card": {"card_id": "cmsg_017ZQamDMHrS6fqMHnQDVo58FnekiCDK9BGVVCqMzSfdkx", "question": "Build ASK 629: a free reserve past a JFL-moved seat, and a clearer failure line?", "answer": "Build it", "press_time": "04:35 CST 2026-11-25"}, "source": "W4's thread note to W3, 05:19 CST 2026-11-25; Wall 11951, 11971; audit 42086. Not read by W3."}$j$::jsonb,
  'W4',
  $j${"md5": "2d000472", "path": "ask629/w4/plan629.md", "note": "plan rev 0, graded PASS WITH R1, N1, N2 by W1 (Wall 11930, commit b1ce6b90)", "source": "md5sum by W3; Wall 11929, 11930"}$j$::jsonb,
  $j$[{"md5": "0e720823", "path": "ask629/w4/b2/tg/target_engine_629.json", "note": "the engine target as written: the b2 rebuild on dc258730", "source": "md5sum by W3; Wall 11957, 11958, 11971, 11975"}, {"md5": "55d96341", "path": "ask629/w4/b1/tg/target_engine_629.json", "note": "the b1 target on 2df7f6fa, the one W1 graded; its two changed nodes are byte-equal to those of b2 (Wall 11957, 11958)", "source": "md5sum by W3; Wall 11951, 11952"}, {"md5": "9c26ace5", "path": "ask629/w4/b1/b629.cjs", "note": "the build script, unchanged in b2", "source": "md5sum by W3; Wall 11951, 11957"}, {"md5": "49af1a26", "path": "ask629/w4/b1/t629.cjs", "note": "the test, unchanged in b2", "source": "md5sum by W3; Wall 11951, 11957"}, {"md5": "afde88ff", "path": "ask629/w4/b2/tg/out_t629.txt", "note": "test output on b2, 39 PASS, 0 FAIL (the count is from Wall 11957; the file was not read by W3)", "source": "md5sum by W3; Wall 11957"}, {"md5": "d4b12e10", "path": "ask629/w4/b1/notes629.md", "note": "build notes", "source": "md5sum and read whole by W3; Wall 11951"}, {"md5": "265443f9", "path": "ask629/w4/write/write629.sh", "note": "the write script (engine only)", "source": "md5sum by W3"}, {"md5": "04d1d9b3", "path": "ask629/w4/write/write629_run.txt", "note": "the write log: PUT engine http 200; 066525aa-beeb-42ad-a92c-e5b6575bed96 active, 423 nodes, params equal put, connections equal, changed Init Seats and Panel Check; child aad0ad9c unchanged; standing 31 PASS, 0 FAIL before and after; Library Check PASSES", "source": "md5sum and read (last lines) by W3"}, {"md5": "b6877882", "path": "ask629/w4/write/fetchback_eng_629.json", "note": "engine fetch-back after the write", "source": "md5sum by W3"}]$j$::jsonb,
  $j${"engine": {"path": "ask629/w4/write/revert_eng_629.json", "md5": "39518a9d", "note": "the engine before ASK 629 (dc258730), made at the write"}, "child": "not written; nothing to revert", "database": "none: no database object was changed", "rehearsed": "not stated in the notes or the Wall posts W3 read", "source": "md5sum by W3; Wall 11971; audit 42086"}$j$::jsonb,
  $j$[{"seat": "W1", "verdict": "PASS WITH R1, N1, N2 (plan rev 0)", "wall_id": 11930, "md5_graded": "2d000472", "verdict_norm": "PASS", "source": "Wall 11930; fairjudge/w1/g629/grade_plan629_r0.md (commit b1ce6b90)"}, {"seat": "W1", "verdict": "PASS WITH N1, N2, N3 (build b1; W1's rebuild equals the target)", "wall_id": 11952, "md5_graded": "55d96341", "verdict_norm": "PASS", "source": "Wall 11952; fairjudge/w1/g629/grade_build629_b1.md (commit 307dc077)"}, {"seat": "W1", "verdict": "REBASE CONFIRMED (build b2 on dc258730: differs from live only on Init Seats and Panel Check, both byte-equal to the graded b1 target; t629 39 PASS on W1's run; the b1 grade PASS WITH N1 to N3 carries)", "wall_id": 11958, "md5_graded": "0e720823", "verdict_norm": "PASS", "source": "Wall 11958 (commit ca8a67e7)"}]$j$::jsonb,
  ARRAY['0e720823'], '[42086]'::jsonb,
  $j$[{"kind": "n8n workflow", "name": "ORACLE_DEBATE_V1 (engine)", "before": "dc258730", "after": "066525aa-beeb-42ad-a92c-e5b6575bed96, active, 423 nodes; two nodes changed: Init Seats (the panel_reserve line) and Panel Check (the no-text throw in envelope()); two lines, each tagged ASK 629; connections equal; no library line changed"}, {"kind": "n8n workflow", "name": "child", "before": "aad0ad9c", "after": "aad0ad9c, not written"}, {"kind": "failure text", "name": "Panel Check, a reply with no text", "before": "\"an envelope this parser does not recognise\"", "after": "\"returned no text: finish_reason <f>; output tokens <n> (reasoning <r>); prompt tokens <p>\"; every other envelope unchanged"}]$j$::jsonb,
  $j$[{"name": "t629.cjs (stored Init Seats inputs of runs 42528, 42517, 42505, 42373, 42283, 42234, 42071; the node outputs of run 42517)", "result": "39 PASS, 0 FAIL by W4 on b1 and b2 and by W1 on its rebuild and on b2. A: only panel_reserve changes on the four replayable runs. A2: an eligible fourth seat is byte-equal; all later seats JFL-moved gives none. C: 42517 replay, old throws as stored, new substitutes hydrogen to sonnet once. B: the detail line; envelope() byte-equal on nine other forms. R1: a substituted reserve is refused as an alternate by G3; an unused reserve is still offered.", "source": "notes629.md; Wall 11951, 11952, 11957, 11958"}, {"name": "Standing set and Library Check pair", "result": "31 PASS, 0 FAIL; pair PASSES, at the build, before the PUT, on the fetch-back and on live (W1)", "source": "Wall 11957, 11971, 11975; write629_run.txt 04d1d9b3"}, {"name": "NOT RUN", "result": "a live run; the majority count code was not read (the change does not touch it); R1's post-substitution payloads were built by hand (W1 N2)", "source": "notes629.md; Wall 11952"}]$j$::jsonb,
  $j$[{"seat": "W1", "result": "MATCH (live engine 066525aa equals the b2 target 0e720823 on every node and connection; only Init Seats and Panel Check changed against dc258730; standing on live 31 PASS, 0 FAIL)", "wall_id": 11975, "source": "Wall 11975 (commit 380785aa)"}]$j$::jsonb,
  $j${"case": "NO RUN YET. Shown offline on stored runs only.", "runs": [], "mark_for_the_next_run": "the JUDGE ORDER line of review_notes reads \"reserve <seat>\" wherever the fourth free seat is JFL-moved and a later seat is free (before: \"reserve none\"). When one panel judge fails, the transcript's substitution line names the reserve and the row is written. When a judge returns no text, the failure detail reads \"returned no text: finish_reason ...\". Two clean live runs are owed; the substitution fires only when a panel judge fails.", "not_shown": "a reserve substitution in a live run; a substituted reserve refused as an alternate in a live run; the no-text line in a live run.", "source": "notes629.md; Wall 11971"}$j$::jsonb,
  $j${"op_doc": "none", "engine_manual": "NOT WRITTEN. Pairs manual1123/w3/a629_635/em_pairs_629_635_draft1.json (833903a5; part 10.0 v311 to 438a0c8d, 63,057; part 16.0 v242 to 616c7193, 2,244) graded PASS WITH N1 by W1 (Wall 11975); draft 2 applies N1 to the part 16.0 pair. The write needs the operator's card. A revision row records the write and the run evidence."}$j$::jsonb,
  'read back', $j$[11919, 11921, 11929, 11930, 11951, 11952, 11957, 11958, 11971, 11975]$j$::jsonb)
RETURNING id)
INSERT INTO ask_aar_builders (snapshot_id, builder_seats, sources, written_by)
SELECT s.id, ARRAY['W4'], $j$[{"seat": "W4", "what": "planned, built, rebuilt on dc258730 and wrote ASK 629 on the operator's build and write cards", "wall_id": 11971}]$j$::jsonb, current_setting('truth.session_id') FROM s;
SELECT * FROM ask_aar_snapshots_check() WHERE row_id = (SELECT max(id) FROM ask_aar_snapshots);
